<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

long double abs_val(long double a) {
    return a < 0 ? -a : a;
}

int main() {
    int a, b, n;
    cin >> a >> b >> n;
    int x, y0, y1;
    long double min_diff = 1e100;
    int res_x = 0, res_y = 0;
    for (int i = 1; i <= n; ++i) {
        x = i;
        y1 = static_cast<int>((static_cast<long double>(a) / b) * i);
        y0 = y1 + 1;
        long double diff1 = abs_val((long double)a / b - (long double)y1 / x);
        long double diff2 = abs_val((long double)a / b - (long double)y0 / x);
        if (min_diff > diff1) {
            min_diff = diff1;
            res_x = y1;
            res_y = x;
        }
        if (min_diff > diff2) {
            min_diff = diff2;
            res_x = y0;
            res_y = x;
        }
    }
    cout << res_x << "/" << res_y << endl;
}
</original_code>
